    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">E = a - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span></span> حيث <span dir=\"ltr\" class=\"expr\">E = -2 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + a</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">E = a - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span></span> حيث <span dir=\"ltr\" class=\"expr\">F = b - 4</span> <span dir=\"ltr\" class=\"expr\">F = 7 - (a + 4 - b) + (-7 + a)</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">E = a - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span></span> حيث <span dir=\"ltr\" class=\"expr\">F = b - 4</span> احسب <span dir=\"ltr\" class=\"expr\">E</span> في حالة <span dir=\"ltr\" class=\"expr\">a = 3</span> <span dir=\"ltr\" class=\"expr\">E = -2 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + a</span><br><span class=\"q\">4) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">E = a - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span></span> حيث <span dir=\"ltr\" class=\"expr\">F = b - 4</span> احسب <span dir=\"ltr\" class=\"expr\">E</span> في حالة <span dir=\"ltr\" class=\"expr\">a = 3</span> أوجد <span dir=\"ltr\" class=\"expr\">b</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">F = 5</span> و <span dir=\"ltr\" class=\"expr\">F = b - 4</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">E = -2 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = a + (-2 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span>)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-2 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> = -<span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span></span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">E = a - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span></span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس المسبوق بعلامة الطرح","math":"<span dir=\"ltr\" class=\"expr\">- (a + 4 - b) = -a - 4 + b</span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"نرفع القوس المسبوق بعلامة الجمع","math":"<span dir=\"ltr\" class=\"expr\">+ (-7 + a) = -7 + a</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">F = 7 - a - 4 + b - 7 + a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">F = (-a + a) + b + (7 - 4 - 7)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">7 - 4 - 7 = -4</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = b - 4</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">E = a - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span></span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">a = 3</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">E = 3 - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">F = b - 4</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(b) - 4 = 5</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">b = 5 - (-4)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b = 9</span>"}],
