    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x + 13</span> حيث <span dir=\"ltr\" class=\"expr\">A = -2 - (x - 15) - [6 - (y + 6)]</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x + 13</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">y - x</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">A = 4</span> و <span dir=\"ltr\" class=\"expr\">A = y - x + 13</span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x + 13</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">y - x</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">A = 4</span> و احسب <span dir=\"ltr\" class=\"expr\">A</span> في حالة <span dir=\"ltr\" class=\"expr\">y = -9</span> و <span dir=\"ltr\" class=\"expr\">x = 6</span> <span dir=\"ltr\" class=\"expr\">A = -2 - (x - 15) - [6 - (y + 6)]</span><br><span class=\"q\">4) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x + 13</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">y - x</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">A = 4</span> و احسب <span dir=\"ltr\" class=\"expr\">A</span> في حالة <span dir=\"ltr\" class=\"expr\">y = -9</span> و <span dir=\"ltr\" class=\"expr\">x = 6</span> <span dir=\"ltr\" class=\"expr\">x - y = 13</span> <span dir=\"ltr\" class=\"expr\">A = y - x + 13</span><br><span class=\"q\">5) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x + 13</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">y - x</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">A = 4</span> و احسب <span dir=\"ltr\" class=\"expr\">A</span> في حالة <span dir=\"ltr\" class=\"expr\">y = -9</span> و <span dir=\"ltr\" class=\"expr\">x = 6</span> <span dir=\"ltr\" class=\"expr\">x - y = 13</span> جد العدد الكسري النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">6 - (9 - x) = 9</span><br><span class=\"q\">6) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x + 13</span> حيث أوجد <span dir=\"ltr\" class=\"expr\">y - x</span> علما و أنّ <span dir=\"ltr\" class=\"expr\">A = 4</span> و احسب <span dir=\"ltr\" class=\"expr\">A</span> في حالة <span dir=\"ltr\" class=\"expr\">y = -9</span> و <span dir=\"ltr\" class=\"expr\">x = 6</span> <span dir=\"ltr\" class=\"expr\">x - y = 13</span> جد العدد الكسري النسبي x بحيث: <span dir=\"ltr\" class=\"expr\">7 + (|x| - 6) = 5</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">- (x - 15) = -x + 15</span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [6 - (y + 6)] = -6 + y + 6</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">A = -2 - x + 15 - 6 + y + 6</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + (-2 + 15 - 6 + 6)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-2 + 15 - 6 + 6 = 13</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + 13</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + 13</span>"},{"quoi":"نستعمل المعطى","math":"<span dir=\"ltr\" class=\"expr\">(y - x) + 13 = 4</span>"},{"quoi":"نعزل المطلوب","math":"<span dir=\"ltr\" class=\"expr\">y - x = 4 - 13</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">y - x = -9</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + 13</span>"},{"quoi":"نكتب المعطى","math":"<span dir=\"ltr\" class=\"expr\">y = -9</span> و <span dir=\"ltr\" class=\"expr\">x = 6</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = (-9) - 6 + 13</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = -2</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + 13</span>"},{"quoi":"نقلب الفرق المعطى","math":"<span dir=\"ltr\" class=\"expr\">y - x = -13</span>"},{"quoi":"نُظهر المعطى","math":"<span dir=\"ltr\" class=\"expr\">A = (y - x) + 13</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = (-13) + 13</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = 0</span>"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"نرفع القوس","math":"<span dir=\"ltr\" class=\"expr\">6 + (-9) + x = 9</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">6 + (-9) = -3</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-3 + x = 9</span>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 9 - (-3)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 12</span>"},{"quoi":"","math":"<b>6)</b>"},{"quoi":"نعزل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|x| = 5 - 7 + 6</span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">5 - 7 + 6 = 4</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">4 &gt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة موجبة، إذن للمعادلة حلاّن متقابلان"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 4</span>  أو  <span dir=\"ltr\" class=\"expr\">x = -4</span>"}],
